import json,pathlib
R=[]
def add(file,method,observation,application,limits,start=None):
 d=dict(repo='Polarice3/Goety-2',file='/'+file+'.java',method=method,observation=observation,application=application,limits=limits)
 if start:d['start']=start
 R.append(d)
add('ServantUtil','nullifyTarget','玩家master且PVP禁用时先标清玩家或玩家宠物；非暴怒时再查同owner、主从关系、ownerStack、自定义ally及离线ownerUUID。IOwned分支直接赋shouldClearTarget会覆盖此前PVP=true。','拒绝许可应单调叠加，不能后续较弱条件将已拒绝结果重置；但本项目直接Enemy-only更窄。','该模组的PVP/暴怒规则不移植。本方法不普遍清非Enemy旁观玩家；不把复杂联盟过滤当Enemy白名单。')
add('ServantFollowOwnerGoal','canUse','要求owner存在且非旁观、距离达到startDistance、isFollowing且未isCommanded、当前无战斗target，最后缓存owner。','跟随goal需要与战斗目标和指令模式互斥；也说明目标一旦被误设就会挤掉跟随。','与Ars跟随不同的是命令/目标门控，未将近似水代价start/stop再计数。')
add('ServantFollowOwnerGoal','canContinueToUse','导航完成或出现战斗target即停止跟随，否则仅检查与缓存owner距离超过stopDistance。','持续阶段会被新战斗目标抢占，解除非法target有助恢复正常跟随。','不会重新检查isFollowing/isCommanded或重新解析owner；只读指出边界，不宣称完整控制。')
add('ServantFollowOwnerGoal','tick','有控制载具时每tick同时导航自身和Mob载具并加速；否则10tick重算，Mob主人32格或失视8格传送，玩家主人16格且配置允许才传送。','同属跟随但主人的类型和载具状态改变动作路径，静态核查须覆盖这些分支。','这不是新增传送需求；相似原生随机落点/水代价模板不重复累计。')
add('ServantReturnToGuardPos','canUse','仅守区模式先让父MoveToBlockGoal找位置，再要求距vec3BoundPos超过range平方。','守卫移动半径与攻击目标许可是两个独立限制，不能把回岗当攻击安全保证。','本项目不新增守区指令；这里研究模式门控和父类搜索顺序。')
add('ServantReturnToGuardPos','findNearestBlock','守区时直接将blockPos赋getBoundPos并按非空返回，否则拒绝。','目标位置应来自当前模式绑定点而非漫游扫描，归属变化要同步失效绑定。','这是移动目标而非攻击实体；与普通nearest目标扫描语义不同，不当建筑参考。')
add('ServantPatrolGoal','canUse','同时要求isPatrolling、无战斗target、当前路点存在才启动巡逻。','非法旧战斗目标会阻断巡逻；归属修复必须避免留下幽灵target。','单独这个方法不保证tick期间模式改变立即退出，持续逻辑须看Goal默认调度。')
add('ModMeleeAttackGoal','canUse','每20gameTick才检测启动；目标需非空存活；可惩罚寻路时按重算计数更新路径，否则以可达路径或已在攻击距离内决定。','20tick节流不能承担授权撤销；原目标一旦存活且近身，寻路失败也仍可开打。','BlackBeast/随从近战子类实际使用此goal；原生风格模板仅作为一份代表，不按各子类端口重复计数。')
add('ModMeleeAttackGoal','canContinueToUse','目标非空存活后，未开启追失视模式时只看导航未结束；另一模式才查restriction和玩家非创造/旁观。','目标持续阶段的分支可能绕开玩家模式过滤，统一Entity许可应独立于导航选项。','没有Enemy或owner检查；这里分析实际随从使用的通用近战goal，不建议改全局野生AI。')
add('ModMeleeAttackGoal','stop','只有目标不符合NO_CREATIVE_OR_SPECTATOR才清target，其余保留；随后取消aggressive并停止导航。','战斗goal退出不必然清旧target，下一轮仍可能重启同一非法目标。','与清owner/Brain是不同层次；不用停止导航冒充彻底撤销攻击资格。')
add('ModMeleeAttackGoal','tick','读取当前target后看向并重算目标位置；按视线/追失视、移动阈值、随机触发重寻路，并叠失败/远距延迟；递减攻击冷却后调用checkAndPerformAttack。','导航延迟不影响最终攻击入口必须检查许可；target可能在长路径间隔内改变。','完整方法未重新判owner/Enemy；同一模板在其他模组或子类若仅改速率不再计数。')
add('ModMeleeAttackGoal','checkAndPerformAttack','仅以攻击距离平方和冷却到期为条件，先重置冷却、挥主手，再调用mob.doHurtTarget。','最后落点若缺统一拒绝会对非法近身目标产生真实攻击；应在最早副作用前阻断。','不将伤害冷却getter/resetter拆成额外条数；实际保护还可由实体重载实现。')
add('ModRangedAttackGoal','canUse','读取mob当前target，非空存活则缓存到goal自身target，否则false但未清旧缓存。','清mob.target不一定清远程goal缓存，目标撤权必须覆盖缓存或最终performRangedAttack。','Warlock/Witch随从实际使用；其匿名重载可换getShootTarget，因此还需检查调用层。')
add('ModRangedAttackGoal','canContinueToUse','canUse为真即续行；否则只要旧缓存target存活且导航未完成仍可继续。','这明确允许mob.target已清后沿旧缓存继续，是定时清target不充分的具体来源。','不直接断言本项目用了该goal；作为同类持续缓存问题参考，不能按多个随从重复算。')
add('ModRangedAttackGoal','stop','将缓存target清空，同时seeTime归零、attackTime设-1，结束当前射击周期。','权限撤销应让远程goal完整停止，缓存目标与蓄势冷却要配对清理。','这一完整清理方法与近战stop保留target不同；不复用为本项目新增蓄力机制。')
add('ModRangedAttackGoal','tick','缓存target空则stop；其他按视线累计seeTime，在距离内且看见5tick停导航，否则追踪；到attackTime零且可见才performRangedAttack，再按距离设下轮冷却。','最终射击读取缓存而非mob当前target，授权失效必须在发射前生效。','没有owner/Enemy重检；同类vanilla风格ranged模板只计本代表，不将子类参数差异凑数。')
add('HurtAlertOtherGoal','canUse','仅新受伤timestamp且来源非空触发；universalAnger开启且来源为Player时拒绝，其余走忽略视线与隐身的TargetingConditions。','反击源可能采用不同的视线规则；玩家排除也可能依赖游戏规则而不是固定许可。','这是目标AI反例而非租约护卫专用实现，本项目不改universalAnger或引入普遍仇恨。')
add('HurtAlertOtherGoal','start','把LastHurtBy写mob.target并缓存targetMob，记timestamp和300tick失视记忆，随后alertOthers再父start。','一次反击不止设置自身目标，还可能传播给周边实体；集中setter仍要覆盖广播入口。','不把单行alertOther再计数，且不建议在本项目新增群体报警。')
add('HurtAlertOtherGoal','alertOthers','以followDistance水平、固定10格垂直查指定predicate的Mob；排自身、已有target和空来源，且非盟友才alertOther设置来源目标。','未结盟不等于Enemy；从周边报警接收的新目标同样要受租约白名单约束。','本方法可能传播对旁观玩家的攻击；只研究过滤边界，普通野生行为仍不改。')
pathlib.Path(__file__).with_name('batch04.json').write_text(json.dumps(R,ensure_ascii=False,indent=2)+'\n')
